import numpy as np

def area_of_ordered_loop(xy):
    x = xy[:,0]; y = xy[:,1]
    return 0.5*np.sum(x*np.roll(y,-1) - np.roll(x,-1)*y)

def polar_pt(r, phi_deg):
    phi = np.radians(phi_deg)
    return np.array([r*np.sin(phi), -r*np.cos(phi)])

